namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy homemade pancakes perfect for weekend mornings.",
            Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
            Steps = "1. Mix dry ingredients together.\n2. Whisk eggs and milk, then combine with dry mix.\n3. Heat a greased pan over medium heat.\n4. Pour batter and cook until bubbles form, then flip.\n5. Serve with maple syrup."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Dinner",
            Description = "A creamy Italian pasta classic with pancetta and parmesan.",
            Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g parmesan\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water.\n2. Fry pancetta until crispy.\n3. Whisk egg yolks with grated parmesan.\n4. Toss hot pasta with pancetta, remove from heat.\n5. Stir in egg mixture quickly. Season with pepper."
        },
        new Recipe
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "Crisp romaine with homemade Caesar dressing and croutons.",
            Ingredients = "1 head romaine lettuce\nCroutons\nParmesan shavings\n1 garlic clove\n2 anchovy fillets\n1 egg yolk\nLemon juice\nOlive oil",
            Steps = "1. Make dressing: blend garlic, anchovies, egg yolk, lemon juice, and oil.\n2. Tear lettuce into bite-sized pieces.\n3. Toss with dressing.\n4. Top with croutons and parmesan shavings."
        },
        new Recipe
        {
            Id = 4, Title = "Chocolate Brownies", Category = "Desserts",
            Description = "Rich, fudgy brownies with a crackly top.",
            Ingredients = "200g dark chocolate\n200g butter\n300g sugar\n3 eggs\n100g flour\n1 tsp vanilla",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk in sugar, then eggs one at a time.\n3. Fold in flour and vanilla.\n4. Pour into lined baking tin.\n5. Bake at 180°C for 25 minutes."
        },
        new Recipe
        {
            Id = 5, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, healthy, and endlessly customizable.",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nChili flakes\nLemon juice",
            Steps = "1. Toast bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread on toast.\n4. Sprinkle with chili flakes."
        },
        new Recipe
        {
            Id = 6, Title = "Chicken Stir Fry", Category = "Dinner",
            Description = "Quick weeknight dinner loaded with vegetables.",
            Ingredients = "2 chicken breasts\n1 bell pepper\n1 cup broccoli\n2 tbsp soy sauce\n1 tbsp sesame oil\nGarlic and ginger",
            Steps = "1. Slice chicken and vegetables.\n2. Heat sesame oil in a wok.\n3. Cook chicken until browned.\n4. Add vegetables, garlic, and ginger.\n5. Pour in soy sauce and stir fry for 3 minutes."
        },
        new Recipe
        {
            Id = 7, Title = "Tomato Soup", Category = "Lunch",
            Description = "Comforting homemade tomato soup with basil.",
            Ingredients = "1 kg ripe tomatoes\n1 onion\n2 garlic cloves\nBasil leaves\nVegetable stock\nOlive oil",
            Steps = "1. Roast halved tomatoes at 200°C for 20 minutes.\n2. Sauté onion and garlic in olive oil.\n3. Add roasted tomatoes and stock.\n4. Simmer 15 minutes, then blend until smooth.\n5. Stir in fresh basil."
        },
        new Recipe
        {
            Id = 8, Title = "Lemon Cheesecake", Category = "Desserts",
            Description = "No-bake lemon cheesecake with a biscuit base.",
            Ingredients = "300g digestive biscuits\n150g melted butter\n500g cream cheese\n200ml double cream\n100g icing sugar\n2 lemons (zest and juice)",
            Steps = "1. Crush biscuits and mix with melted butter. Press into tin base.\n2. Beat cream cheese with icing sugar.\n3. Whip cream to soft peaks, fold into cheese mix.\n4. Add lemon zest and juice.\n5. Pour over base and refrigerate 4 hours."
        }
    };

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }
}

